INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (47, 89, '公司简介', '../upload/image/20180828/20180828150800_23872.png', '<p></p><div class="col-md-4 fashion-img1"> <p>Is a collection of production, research and development and sales for the integration of a large multinational group of companies. In today''s global market economy condition, the company full participation in the quality of the products at home and abroad, price and service competition. <br/> <br/> Take the market as the guide, is committed to export-oriented (export-oriented) the development of the economy. Group relying on mainland China land resources labor cost advantage and advantage of government''s policy</p> </div> <div class="col-md-4 fashion-img1"> <p>of opening to the outside world, vigorously the introduction of modern production lines, the economies of scale and intensive economic road, increase investment in scientific research project, encourage scientific and technological personnel to product innovation, timely to adapt to the global customers increasingly fine specialization, diversification, personalization...</p> </div>', '2026-09-06 20:58:46');